using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.City;
using CashflowChains.Economy;
using CashflowChains.Empire;
public sealed class CityResidentProfilesTests {
 BalanceConfig c;
 [SetUp]public void Setup(){c=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));c.Validate();}
 CityOperatingPlan Plan(params CityProperty[] p)=>new CityOperatingPlan{Day=1,StartAt=100,FinishAt=105,CashAvailable=1000,Properties=p,Inventory=new[]{new ItemAmount("BEANS",10),new ItemAmount("CUPS",10)}};
 [Test]public void NewCityHasNoFreeHouseAndNoPeopleBeforePaidConstructionCompletes(){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="empty-start"}},_=>true);e.OpenCity(100);Assert.AreEqual(0,e.Snapshot.City.Properties.Count);Assert.AreEqual(0,e.ForecastCity().Population);Assert.Throws<InvalidOperationException>(()=>e.BuildCity("no-workers","cafe",2,1,101));e.BuildCity("home","home",1,1,102);Assert.AreEqual(120,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(6,e.Snapshot.Economy.Amount("WOOD"));Assert.AreEqual(0,e.ForecastCity().Population);Assert.Throws<InvalidOperationException>(()=>e.FinishCityBuild("home",104));e.FinishCityBuild("home",105);Assert.AreEqual(4,e.ForecastCity().Population);}
 [Test]public void HouseholdsHaveDifferentAgeCompositionAndSizes(){var family=CityResidents.Household(1,0,1);var retired=CityResidents.Household(3,0,1);var single=CityResidents.Household(4,0,1);Assert.AreEqual(4,family.Length);Assert.AreEqual(2,family.Count(p=>p.Age<18));Assert.AreEqual(2,retired.Length);Assert.True(retired.All(p=>p.Senior));Assert.False(retired.Any(p=>p.WorkingAge));Assert.AreEqual(1,single.Length);}
 [Test]public void ChildrenCannotWorkOrGenerateCoffeeOrders(){foreach(int id in new[]{1,2,3,4,5,6})foreach(var p in CityResidents.Household(id,0,1))if(p.Age<18){Assert.False(p.WorkingAge);Assert.False(p.LikesCoffee);Assert.AreEqual(0,p.DailyBudget);}}
 [Test]public void AgingChangesRetirementEligibilityWithoutChangingResidentIdentity(){var first=CityResidents.Household(4,0,1).Single();var later=CityResidents.Household(4,0,28*365+1).Single();Assert.AreEqual(first.Id,later.Id);Assert.AreEqual(first.Gender,later.Gender);Assert.True(first.WorkingAge);Assert.False(later.WorkingAge);Assert.True(later.Senior);}
 [Test]public void MovingHomesCannotRerollTheResidentProfiles(){var p=new CityProperty{Id=1,Kind="home",Level=1};string before=string.Join(";",CityHousing.Occupancy(c.City,new[]{p},1).Single().Families.Single().Select(r=>r.Id+":"+r.Age+":"+r.Gender+":"+r.DailyBudget));p.X=3;p.Y=3;string after=string.Join(";",CityHousing.Occupancy(c.City,new[]{p},1).Single().Families.Single().Select(r=>r.Id+":"+r.Age+":"+r.Gender+":"+r.DailyBudget));Assert.AreEqual(before,after);}
 [Test]public void AHomeOfRetireesDoesNotMagicallyStaffTheCafe(){var r=CityDayModel.Forecast(c.City,Plan(new CityProperty{Id=3,Kind="home",Level=1},new CityProperty{Id=4,Kind="cafe",Level=1,Staff=1,X=1}));Assert.AreEqual(2,r.Population);Assert.AreEqual(2,r.Seniors);Assert.AreEqual(0,r.Workers);Assert.AreEqual(0,r.Jobs);Assert.AreEqual(0,r.Businesses.Single(b=>b.Kind=="cafe").Employees);Assert.AreEqual(0,r.CoffeeServed);}
 [Test]public void CustomerBudgetsPreventSalesAndStockConsumptionTheyCannotAfford(){c.City.Business("cafe").Price=500;c.City.CompetitorWeight=1;var r=CityDayModel.Forecast(c.City,Plan(new CityProperty{Id=1,Kind="home",Level=1},new CityProperty{Id=2,Kind="cafe",Level=1,Staff=1,X=1}));Assert.AreEqual(2,r.CoffeeDemand);Assert.AreEqual(0,r.CoffeeServed);Assert.AreEqual(0,r.Businesses.Single(b=>b.Kind=="cafe").Revenue);Assert.AreEqual(0,r.Resources.Single(s=>s.ItemId=="BEANS").Consumed);}
 [Test]public void GenderCountsReconcileWithTheActualResidentCensus(){var r=CityDayModel.Forecast(c.City,Plan(new CityProperty{Id=1,Kind="home",Level=2},new CityProperty{Id=2,Kind="cafe",Level=1,X=1}));Assert.AreEqual(r.Population,r.Women+r.Men+r.NonBinary);Assert.AreEqual(r.Population,r.Adults+r.Children);Assert.LessOrEqual(r.Workers,r.Adults);}
 [Test]public void ACommittedCatalogFiveDayKeepsItsPromiseAcrossTheProfileMigration(){var old=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-legacy-city-v5.json")));var e=new EmpireEngine(old,new EmpireAccount{Economy=new EconomyState{AccountId="profile-migration"}},_=>true);e.OpenCity(100);e.BuildCity("cafe","cafe",2,1,101);e.FinishCityBuild("cafe",104);e.StartCityDay(105);var original=e.CurrentCityDay();var loaded=JsonUtility.FromJson<EmpireAccount>(JsonUtility.ToJson(e.Snapshot));loaded.Validate(c);var next=new EmpireEngine(c,loaded,_=>true);Assert.AreEqual(original.Net,next.CurrentCityDay().Net);next.SettleCityDay(1,110);Assert.AreEqual(4,next.ForecastCity().Population);Assert.AreEqual(1,next.Snapshot.City.Properties[0].LegacyFamilies);}
 [Test]public void OldHouseholdDaysKeepTheirOriginalAdultCountAtLateDates(){var p=Plan(new CityProperty{Id=1,Kind="home",Level=1},new CityProperty{Id=2,Kind="cafe",Level=1,X=1});p.HousingRules=1;p.Day=10000;var r=CityDayModel.Forecast(c.City,p);Assert.AreEqual(4,r.Population);Assert.AreEqual(2,r.Adults);Assert.AreEqual(2,r.CoffeeDemand);}

 [Test]public void FoundingFundsCannotBeSpentIntoAHouseAndCafeSoftlock(){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="founding-budget"}},_=>true);e.OpenCity(100);Assert.Throws<InvalidOperationException>(()=>e.ExpandCity("too-early",true,101));Assert.Throws<InvalidOperationException>(()=>e.BuyCityMaterials("waste-budget","WOOD",20,102));Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));e.BuildCity("first-home","home",1,1,103);e.FinishCityBuild("first-home",106);Assert.Throws<InvalidOperationException>(()=>e.BuildCity("extra-home","home",0,1,107));Assert.AreEqual(120,e.Snapshot.Economy.Amount("CASH"));e.BuildCity("first-cafe","cafe",2,1,108);Assert.AreEqual(20,e.Snapshot.Economy.Amount("CASH"));}

}
